 void title(){std::wstring t=(studio?std::wstring(L"Rally Workshop — 3D Viewport | "):std::wstring(L"Master Rallye Vehicle Previewer | "))+source.filename().wstring()+L" | "+(model==1?(assembled?L"assembled race":L"raw race"):model==2?L"frontend":L"wheel")+L" | "+(brake?L"BRAKE ON":L"brake off")+(reflections?L" | reflections":L" | no reflections");
  t+=cull==D3DCULL_NONE?L" | cull NONE (diagnostic)":cull==D3DCULL_CW?L" | cull CW":L" | cull CCW";
  t+=instanceDepth?L" | instance ZWrite ON":L" | shader ZWrite";
  if(layer>=0&&layer<int(draws.size()))t+=L" | "+wide(draws[layer].name);if(!error.empty())t+=L" | ERROR: "+error;SetWindowTextW(window,t.c_str());}
 V3 eyePosition()const{return centre+V3{std::sin(az)*std::cos(el),std::sin(el),std::cos(az)*std::cos(el)}*distance;}
 void pan(float dx,float dy){RECT r;GetClientRect(window,&r);V3 z=norm(eyePosition()-centre),right=norm(cross({0,1,0},z)),up=cross(z,right);float scale=2*distance*std::tan(.3f)/std::max(1L,r.bottom);centre=centre+right*(-dx*scale)+up*(dy*scale);}
