 void focusSelected(){if(selected<0||selected>=int(draws.size())){resetCamera();return;}const auto&d=draws[selected];if(d.v.empty())return;V3 lo=d.v[0].p,hi=lo;for(auto&v:d.v)for(int k=0;k<3;k++){(&lo.x)[k]=std::min((&lo.x)[k],(&v.p.x)[k]);(&hi.x)[k]=std::max((&hi.x)[k],(&v.p.x)[k]);}centre=(lo+hi)*.5f;radius=std::max(.01f,std::sqrt(dot(hi-lo,hi-lo))*.5f);distance=radius*3.8f;}
