 void key(WPARAM k){if(k>='1'&&k<='6'){if(GetKeyState(VK_CONTROL)&0x8000)bookmark(int(k-'0'),true);else if(GetKeyState(VK_SHIFT)&0x8000)bookmark(int(k-'0'),false);else camera(int(k-'0'));}else if(k=='A')assembled=!assembled;else if(k==VK_F3)hud=!hud;else if(k==VK_HOME){resetCamera();camera(4);}else if(k=='V')bookmark(1,false);else if(k=='S')bookmark(1,true);else if(k=='I')resourceInfo();else if(k=='R')rebuild();else if(k=='O')open();else if(k==VK_TAB){model=model%3+1;resetCamera();}else if(k=='E')reflections=!reflections;else if(k=='B')brake=!brake;else if(k=='W')wire=!wire;else if(k=='C')alternate=!alternate;else if(k=='D')mode=(mode+1)%3;else if(k=='K')cull=cull%3+1;else if(k=='Z')instanceDepth=!instanceDepth;else if(k=='L'){for(size_t n=0;n<=draws.size();n++){layer++;if(layer>=int(draws.size())){layer=-1;break;}if(draws[layer].model==uint32_t(model)||draws[layer].model==0)break;}}else if(k=='0')layer=-1;else if(k=='F')focusSelected();else if(k==VK_F1)MessageBoxW(window,L"LMB: orbit / click geometric pick | MMB: pan | wheel: zoom\nF3: debug HUD | Home: reset | Ctrl1..6 save / Shift1..6 recall\nA: raw/assembled Race (only qualified staged wheels)\n1 Front/outside  2 Rear/inside  3 Side  4 Three-quarter  5 Top  6 Opposite side\nK: culling CCW / NONE / CW | Z: instance/shader ZWrite\nTab: race/frontend/wheel | F: frame | R: reload DX\nO: open DX | E: reflections | B: brake state\nI: resource counts and selected layer texture dimensions\nC: alternate generic switch case | W: wireframe\nD: composed/base/vertex-only | L: isolate next layer | 0: all layers\n\nFixed-function diagnostic approximation. Runtime world lighting, fog, exact sorting and inherited instance states differ. Race wheels need a provenance-bearing rest-pose profile. No physics is simulated.",L"Vehicle Previewer",MB_OK);title();}
